package grammar

func init() {
	planFlag := required("plan", "ID|URN", "plan id or URN")
	taskFlag := required("task", "ID|URN", "task id, or a task URN, which names its plan")
	optionalPlanFlag := optional("plan", "ID|URN", "plan id or URN; required unless --task is a task URN")
	repoFlag := optional("repo", "PATH", "code checkout when separate")
	agentFlag := optional("agent", "NAME", "who is reporting; defaults to the DevSwarm workspace, else the Git branch")
	commands = append(commands,
		Command{Name: "plan add-phase", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan add-phase --plan ID|URN --id ID --title TEXT [--after PHASE] [--checkpoint] [--json] <saga>", Summary: "add a named phase to the end of a Plan's order, or after --after; a phase's tasks run in parallel, and depend only on earlier phases. --checkpoint makes it a checkpoint: it holds no tasks, covers every task since the previous checkpoint, and holds the work after it until it passes", Flags: []Flag{planFlag, required("id", "ID", "stable phase id"), required("title", "TEXT", "phase title"), optional("after", "PHASE", "put it right after this phase"), optional("checkpoint", "", "make it a checkpoint"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan add-name", Status: StatusImplemented, Mutates: true, Writes: []string{"name"}, Usage: "change-saga plan add-name --plan ID|URN --id ID --title TEXT [--summary TEXT] [--parent NAME] [--link NAME[=LABEL]...] [--record URN] [--json] <saga>", Summary: "add a name to a Plan: a label for an abstraction it works on; a top-level name says what the Plan works on, and --parent puts a more detailed name beneath another; Tasks name names with task set --name, which checks them off as they finish", Flags: []Flag{planFlag, required("id", "ID", "stable name id"), required("title", "TEXT", "the name"), optional("summary", "TEXT", "what the name hides"), optional("parent", "NAME", "the name this one details"), repeatable("link", "NAME[=LABEL]", "a name this one links to", false), optional("record", "URN", "a term, component, or system the name means"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan set-name", Status: StatusImplemented, Mutates: true, Writes: []string{"name"}, Usage: "change-saga plan set-name --plan ID|URN --id ID [--title TEXT] [--summary TEXT] [--parent NAME] [--link NAME[=LABEL]...] [--record URN] [--json] <saga>", Summary: "change a name; --parent with an empty value makes it top-level, --link replaces its links, and a move that would close a cycle is refused", Flags: []Flag{planFlag, required("id", "ID", "name id"), optional("title", "TEXT", "the name"), optional("summary", "TEXT", "what the name hides; empty clears it"), optional("parent", "NAME", "the name this one details; empty makes it top-level"), repeatable("link", "NAME[=LABEL]", "replaces the name's links; one empty value clears them", false), optional("record", "URN", "a term, component, or system; empty clears it"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan remove-name", Status: StatusImplemented, Mutates: true, Writes: []string{"name"}, Usage: "change-saga plan remove-name --plan ID|URN --id ID [--json] <saga>", Summary: "delete a name; refused, naming each, while a name beneath it, a link, or a Task still names it", Flags: []Flag{planFlag, required("id", "ID", "name id"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan names", Status: StatusImplemented, Usage: "change-saga plan names --plan ID|URN [--json] <saga>", Summary: "print a Plan's names as a tree, each checked off by the Tasks beneath it, then the Tasks on no name (unexpected work) and the names no Task reaches (possibly unneeded)", Flags: []Flag{planFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan remove-phase", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan remove-phase --plan ID|URN --id ID [--json] <saga>", Summary: "remove a phase no task is in; add phases again to reorder them", Flags: []Flag{planFlag, required("id", "ID", "phase id"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan add-prototype", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan add-prototype --plan ID|URN --prototype URN [--json] <saga>", Summary: "attach a prototype that shows what a Plan will build", Flags: []Flag{planFlag, required("prototype", "URN", "prototype URN"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan create", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan create --id ID --title TEXT [--objective TEXT] [--json] <saga>", Summary: "create a Plan and its empty deck: one body of work, where its technical design is drafted", Flags: []Flag{required("id", "ID", "stable plan id"), required("title", "TEXT", "plan title"), optional("objective", "TEXT", "what the plan's deck explains"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan deliver", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan deliver --plan ID|URN [--repo PATH] [--json] <saga>", Summary: "mark a Plan delivered, which hides it by default as a merged review is hidden; refused unless every Task is done, at least one Review is linked, and every linked Review has merged", Flags: []Flag{planFlag, repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan guide", Status: StatusImplemented, Usage: "change-saga plan guide [--plan ID|URN] <saga>", Summary: "print the guided way to a Plan you can be confident in; with --plan, also name the Tasks not yet confidently two days or less, and what the deck still needs", Flags: []Flag{optional("plan", "ID|URN", "report what this Plan still needs")}, Positionals: sagaOnly},
		Command{Name: "plan link-review", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan link-review --plan ID|URN --review ID [--checkpoint PHASE] [--json] <saga>", Summary: "record a pull request review that implements a Plan; the review shows the link back", Flags: []Flag{planFlag, optional("checkpoint", "PHASE", "the checkpoint this review covers"), required("review", "ID", "review id"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan list", Status: StatusImplemented, Usage: "change-saga plan list [--feature ID] [--story URN] [--all] [--json] <saga>", Summary: "list the Plans with their Task progress and the stories and features their Tasks reach; the text hides delivered Plans unless --all", Flags: []Flag{optional("feature", "ID", "only Plans whose Tasks reach a story in this feature"), optional("story", "URN", "only Plans with a Task naming this story"), optional("all", "", "also print delivered Plans"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task add", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task add --plan ID|URN --id ID --title TEXT (--story URN | --unblocks TASK...) [--depends-on TASK...] [--phase ID] [--essay-source FILE|-] [--code PATH:START-END[=NOTE]...] [--sizing within-2-days|over-2-days] [--sizing-reason TEXT] [--name NAME...] [--repo PATH] [--json] <saga>", Summary: "add a Task to a Plan; it must name a user story or unblock a Task that leads to one, and is refused otherwise", Flags: []Flag{planFlag, required("id", "ID", "stable task id"), required("title", "TEXT", "task title"), optional("story", "URN", "the user story this task is part of"), repeatable("unblocks", "TASK", "a task that depends on this one", false), repeatable("depends-on", "TASK", "a task this one depends on", false), optional("phase", "ID", "phase id"), optional("essay-source", "FILE|-", "Markdown essay"), repeatable("code", "PATH:START-END[=NOTE]", "code to pin at HEAD", false), optional("sizing", "VALUE", "within-2-days or over-2-days: whether one human developer, coding without AI help, would finish this in two days or less"), optional("sizing-reason", "TEXT", "why"), repeatable("name", "NAME", "a name of the Plan this task works on", false), repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task depend", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task depend [--plan ID|URN] --task ID|URN --on TASK [--remove] [--json] <saga>", Summary: "add or remove a dependency between two Tasks of a Plan; refused when it would make a cycle or strand a Task", Flags: []Flag{optionalPlanFlag, taskFlag, required("on", "TASK", "the task it depends on"), optional("remove", "", "remove the dependency instead"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task done", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task done [--plan ID|URN] --task ID|URN [--summary TEXT] [--agent NAME] [--repo PATH] [--json] <saga>", Summary: "mark a Task done, as an agent does when it finishes; the slides that name it show this without being republished, and a reader on another worktree sees it live; it never proves the work is correct", Flags: []Flag{optionalPlanFlag, taskFlag, optional("summary", "TEXT", "what was done"), agentFlag, repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan checkpoint", Status: StatusImplemented, Usage: "change-saga plan checkpoint --plan ID|URN --checkpoint PHASE [--json] <saga>", Summary: "report a checkpoint: the tasks it covers, the stories they address, about how many slides it takes to explain, what would make passing it surprising, and what to do next", Flags: []Flag{planFlag, required("checkpoint", "PHASE", "the checkpoint phase"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan pass", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan pass --plan ID|URN --checkpoint PHASE --reason TEXT (--by NAME | --agent) [--met ID=HOW...] [--repo PATH] [--json] <saga>", Summary: "record that a checkpoint passed, so the work after it may start; refused until every task it covers is done and every earlier checkpoint passed, and refused to an agent unless the Plan lets agents pass; then merge the checkpoint's branch into the Plan's feature branch", Flags: []Flag{planFlag, required("checkpoint", "PHASE", "the checkpoint phase to pass"), required("reason", "TEXT", "why it passes: what proves the work works"), optional("by", "NAME", "who passes it"), optional("agent", "", "an agent passes it, under the invoker's rule"), repeatable("met", "ID=HOW", "how one of its expectations was shown to hold", false), repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan expect", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan expect --plan ID|URN --checkpoint PHASE --id ID (--statement TEXT | --remove) [--json] <saga>", Summary: "state what must be true by a checkpoint: an invariant or characteristic of the work, not a user story; plan pass then needs --met ID=HOW for each", Flags: []Flag{planFlag, required("checkpoint", "PHASE", "the checkpoint phase"), required("id", "ID", "stable expectation id"), optional("statement", "TEXT", "what must be true"), optional("remove", "", "remove the expectation instead"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan widen", Status: StatusImplemented, Mutates: true, Writes: []string{"review"}, Usage: "change-saga plan widen --plan ID|URN --checkpoint PHASE --to PHASE [--json] <saga>", Summary: "widen a checkpoint's review to show every change since an earlier checkpoint's review began, or with --to the checkpoint itself, only its own stretch again; it never changes what the review merges into", Flags: []Flag{planFlag, required("checkpoint", "PHASE", "the checkpoint whose review to widen"), required("to", "PHASE", "an earlier checkpoint, or the checkpoint itself"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan set", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan set --plan ID|URN --checkpoint-passer person|agent [--json] <saga>", Summary: "say who passes the Plan's checkpoints: a person, or an agent, which passes them unless what it found is surprising or urgent", Flags: []Flag{planFlag, required("checkpoint-passer", "WHO", "person or agent"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task start", Status: StatusImplemented, Usage: "change-saga task start [--plan ID|URN] --task ID|URN [--agent NAME] [--repo PATH] [--json] <saga>", Summary: "say you picked a Task up, as live activity every worktree of this repository sees; it writes nothing to the Saga, and warns when someone else is on the Task", Flags: []Flag{optionalPlanFlag, taskFlag, agentFlag, repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task note", Status: StatusImplemented, Usage: "change-saga task note [--plan ID|URN] --task ID|URN [--blocked] [--agent NAME] [--repo PATH] [--json] <message> <saga>", Summary: "leave a short message on a Task, or say it is blocked, as live activity every worktree of this repository sees; it writes nothing to the Saga. A later note clears blocked", Flags: []Flag{optionalPlanFlag, taskFlag, optional("blocked", "", "the Task cannot go on until someone acts"), agentFlag, repoFlag, jsonFlag}, Positionals: []string{"<message>", "<saga>"}},
		Command{Name: "task list", Status: StatusImplemented, Usage: "change-saga task list --plan ID|URN [--ready] [--repo PATH] [--json] <saga>", Summary: "list a Plan's Tasks with who is on them; --ready lists what can start now, in parallel, because everything it depends on is done, and says when someone has started one", Flags: []Flag{planFlag, optional("ready", "", "only Tasks that can start now"), repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task remove", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task remove [--plan ID|URN] --task ID|URN [--json] <saga>", Summary: "delete a Task and every dependency on it; refused when that would strand a Task or a slide still names it", Flags: []Flag{optionalPlanFlag, taskFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task set", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task set [--plan ID|URN] --task ID|URN [--title TEXT] [--phase ID] [--story URN] [--state STATE] [--essay-source FILE|-] [--code PATH:START-END[=NOTE]...] [--sizing within-2-days|over-2-days] [--sizing-reason TEXT] [--name NAME...] [--repo PATH] [--agent NAME] [--json] <saga>", Summary: "change a Task's fields; refused when the result would strand a Task or name a name the Plan does not have", Flags: []Flag{optionalPlanFlag, taskFlag, optional("title", "TEXT", "task title"), optional("phase", "ID", "phase id; empty clears it"), optional("story", "URN", "user story; empty clears it"), optional("state", "STATE", "planned, in_progress, or done"), optional("essay-source", "FILE|-", "Markdown essay; an empty file removes it"), repeatable("code", "PATH:START-END[=NOTE]", "code to pin at HEAD; replaces the task's references", false), optional("sizing", "VALUE", "within-2-days or over-2-days"), optional("sizing-reason", "TEXT", "why"), repeatable("name", "NAME", "a name of the Plan this task works on; replaces its names, and one empty value clears them", false), repoFlag, agentFlag, jsonFlag}, Positionals: sagaOnly},
	)
	resources = append(resources,
		Resource{Kind: "plan", URN: "urn:change-saga:<saga>:plan:<plan>", Storage: "___plans/<plan>.plan/plan.json and deck/ (a flat deck bundle, role plan)", Schema: schemaBase + "v5/plan.schema.json", Versions: []int{5}, History: "editable current state; Git keeps the history; a delivered Plan no longer changes", Writers: []string{"plan create", "plan add-phase", "plan remove-phase", "plan add-prototype", "plan link-review", "plan deliver"}, Notes: "one body of work, in its own section beside Documentation and Reviews; it belongs to no feature, and its stories and features are worked out from its Tasks; its slide and Item URNs are <plan>:slide:<slide>[:item:<item>]; it never counts toward coverage"},
		Resource{Kind: "name", URN: "urn:change-saga:<saga>:plan:<plan>:name:<name>", Storage: "___plans/<plan>.plan/names/<name>.name/name.json", Schema: schemaBase + "v5/name.schema.json", Versions: []int{5}, History: "editable current state; Git keeps the history", Writers: []string{"plan add-name", "plan set-name", "plan remove-name"}, Notes: "a label for an abstraction a Plan works on, with at most one parent name, labeled links to other names, and an optional term, component, or system it means; Tasks name names, and a name's progress is derived from the Tasks beneath it"},
		Resource{Kind: "task", URN: "urn:change-saga:<saga>:plan:<plan>:task:<task>", Storage: "___plans/<plan>.plan/tasks/<task>.task/task.json and optional essay.md", Schema: schemaBase + "v5/task.schema.json", Versions: []int{5}, Lifecycle: []string{"planned", "in_progress", "done"}, History: "editable current state; Git keeps the history", Writers: []string{"task add", "task depend", "task set", "task done", "task remove"}, Notes: "must name a user story or unblock a Task that leads to one; what it unblocks is derived from depends_on, and dependencies stay inside one Plan"},
	)
}
